import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
# Hypothesis: output rows = expand(input rows reflected) with pattern 0..H-1, H-1..0, 0..H-1, each row doubled w/o-gap.
def f(inG):
    H,W=len(inG),len(inG[0])
    R=inG[::-1][:]; R=map(lambda r: r[::-1], R)
    L=list(R)
    def dbl(r): return r+r[::-1]
    rows=[]
    for i in range(H): rows.append(dbl(L[i]))
    for i in range(H-1,-1,-1): rows.append(dbl(L[i]))
    for i in range(H): rows.append(dbl(L[i]))
    return rows
for k in ['Demo pair 2','Demo pair 3','Demo pair 4']:
    pred=f(G[k+' input']); act=G[k+' output']
    print(k,'pred==act:',pred==act)
